import math

def count_binary_seq(n):
    # Calculate the number of ways to choose k ones out of n bits
    def binomial_coefficient(n, k):
        return math.comb(n, k)

    # Total count of valid sequences
    total_count = 0

    # Iterate over all possible values of k (from 0 to n)
    for k in range(n + 1):
        # Square the binomial coefficient for each k
        total_count += binomial_coefficient(n, k) ** 2

    # Return the result as a floating-point number
    return float(total_count)

