    Finds the index of the first occurrence of a given number in a sorted array.

    Parameters:
    arr (list): The sorted array to search.
    x (int): The number to find.

    Returns:
    int: The index of the first occurrence of x in arr, or -1 if x is not found.
    """
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] < x:
                return mid
            else:
                high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return -1

