def bell_Number(n):
    # Initialize a list to store Bell numbers
    Bell = [0] * (n + 1)

    # Base cases
    Bell[0] = 1
    if n > 0:
        Bell[1] = 1

    # Calculate Bell numbers using dynamic programming
    for i in range(2, n + 1):
        Bell[i] = 0
        for j in range(i):
            Bell[i] += Bell[j]

    return Bell[n]

